#!/usr/bin/env bash
set -euo pipefail

cd "$(dirname "$0")"

BASE_HREF="${1:-/}"

# Keep the in-app version label in sync with pubspec.yaml.
VERSION_LINE="$(grep -E '^version:' pubspec.yaml | head -1 | sed -E 's/^version:[[:space:]]*//')"
APP_VERSION="${VERSION_LINE%%+*}"
BUILD_NUMBER="${VERSION_LINE##*+}"
cat > lib/core/app_version.dart <<EOF
/// Generated by build-web.sh from pubspec.yaml — do not edit manually.
const String appVersion = '$APP_VERSION';
const String appBuildNumber = '$BUILD_NUMBER';
EOF

echo "==> flutter build web --release --base-href $BASE_HREF"
flutter build web --release --base-href "$BASE_HREF"

OUT="build/web/index.html"
if grep -q "<base href=\"$BASE_HREF\"" "$OUT"; then
    echo "OK  base href benar: $BASE_HREF"
else
    echo "OK  (periksa base href di $OUT)"
fi

printf '{"app_name":"id_animate","version":"%s","build_number":"%s","package_name":"id_animate"}' \
  "$APP_VERSION" "$BUILD_NUMBER" > build/web/version.json

echo
echo "==> Selesai. Build tersimpan di build/web"
echo "    Demo site : /var/www/id-animate/app/build/web (nginx root)"
echo "    URL       : https://demo-id-animate.zet.web.id/"
